function configureBoldLinkBraceletSku(){if(handle!=='hardware-u-link-bracelet')return;const app=document.querySelector('#app');if(!app||app.dataset.boldLinkReady||!app.querySelector('#thumbs button'))return;app.dataset.boldLinkReady='true';const thumbBox=app.querySelector('#thumbs');const paint=images=>{app.querySelector('#mainImage').src=`${images[0]}?width=1600`;thumbBox.innerHTML=images.map((image,i)=>`<button class="clover-thumb ${i?'':'active'}" data-image="${safe(image)}?width=1600"><img src="${safe(image)}" alt="Hardware U Link Bracelet image ${i+1}"></button>`).join('');thumbBox.querySelectorAll('button').forEach(button=>button.onclick=()=>{app.querySelector('#mainImage').src=button.dataset.image;thumbBox.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===button))})};app.querySelectorAll('#colors button').forEach(button=>button.addEventListener('click',()=>paint(boldLinkBraceletImages[button.textContent]||boldLinkBraceletImages['Yellow Gold'])));}
new MutationObserver(configureBoldLinkBraceletSku).observe(document.querySelector('#app'),{childList:true,subtree:true});configureBoldLinkBraceletSku();
